"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[37145],{3331:(e,i,a)=>{a.d(i,{R:()=>l,x:()=>o});var r=a(36672);const t={},n=r.createContext(t);function l(e){const i=r.useContext(n);return r.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function o(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:l(e.components),r.createElement(n.Provider,{value:i},e.children)}},74241:(e,i,a)=>{a.r(i),a.d(i,{assets:()=>c,contentTitle:()=>o,default:()=>d,frontMatter:()=>l,metadata:()=>r,toc:()=>u});const r=JSON.parse('{"id":"2023/04/14","title":"2023-04-14","description":"Arestare f\u0103cut\u0103 \xeen SF uciderea lui Bob Lee - presupusul uciga\u0219 a lucrat, de asemenea, \xeen tehnologie","source":"@site/i18n/ro/docusaurus-plugin-content-docs/current/2023/04/14.md","sourceDirName":"2023/04","slug":"/2023/04/14","permalink":"/ro/2023/04/14","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/ro/docusaurus-plugin-content-docs//current/2023/04/14.md","tags":[],"version":"current","frontMatter":{"localized_date":"14 aprilie 2023","top_news":"Arestare f\u0103cut\u0103 \xeen SF uciderea lui Bob Lee - presupusul uciga\u0219 a lucrat, de asemenea, \xeen tehnologie"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-15","permalink":"/ro/2023/04/15"},"next":{"title":"2023-04-13","permalink":"/ro/2023/04/13"}}');var t=a(23420),n=a(3331);const l={localized_date:"14 aprilie 2023",top_news:"Arestare f\u0103cut\u0103 \xeen SF uciderea lui Bob Lee - presupusul uciga\u0219 a lucrat, de asemenea, \xeen tehnologie"},o="2023-04-14",c={},u=[{value:"Arestare f\u0103cut\u0103 \xeen SF uciderea lui Bob Lee - presupusul uciga\u0219 a lucrat, de asemenea, \xeen tehnologie",id:"arestare-f\u0103cut\u0103-\xeen-sf-uciderea-lui-bob-lee---presupusul-uciga\u0219-a-lucrat-de-asemenea-\xeen-tehnologie",level:2},{value:"Interzicerea g\u0103zduirii YouTube-DL deschide calea c\u0103tre cenzura privatizat\u0103",id:"interzicerea-g\u0103zduirii-youtube-dl-deschide-calea-c\u0103tre-cenzura-privatizat\u0103",level:2},{value:"The art of auto engineering",id:"the-art-of-auto-engineering",level:2},{value:"Apple va folosi cobalt 100% reciclat \xeen baterii p\xe2n\u0103 \xeen 2025",id:"apple-va-folosi-cobalt-100-reciclat-\xeen-baterii-p\xe2n\u0103-\xeen-2025",level:2},{value:"Am ob\u021binut o cre\u0219tere de 6 ori a vitezei de pornire a Podman",id:"am-ob\u021binut-o-cre\u0219tere-de-6-ori-a-vitezei-de-pornire-a-podman",level:2},{value:"Improving Tailscale via Apple&#39;s open source",id:"improving-tailscale-via-apples-open-source",level:2},{value:"Desene animate",id:"desene-animate",level:2},{value:"Amazon CodeWhisperer, gratuit pentru utilizare individual\u0103, este acum disponibil \xeen general",id:"amazon-codewhisperer-gratuit-pentru-utilizare-individual\u0103-este-acum-disponibil-\xeen-general",level:2},{value:"Google a retras deja \u0219ase produse \xeen 2023",id:"google-a-retras-deja-\u0219ase-produse-\xeen-2023",level:2},{value:"Nvidia RTX Remix Runtime Open Source disponibil acum",id:"nvidia-rtx-remix-runtime-open-source-disponibil-acum",level:2}];function s(e){const i={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(i.header,{children:(0,t.jsx)(i.h1,{id:"2023-04-14",children:"2023-04-14"})}),"\n",(0,t.jsx)(i.h2,{id:"arestare-f\u0103cut\u0103-\xeen-sf-uciderea-lui-bob-lee---presupusul-uciga\u0219-a-lucrat-de-asemenea-\xeen-tehnologie",children:"Arestare f\u0103cut\u0103 \xeen SF uciderea lui Bob Lee - presupusul uciga\u0219 a lucrat, de asemenea, \xeen tehnologie"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://missionlocal.org/2023/04/bob-lee-killing-arrest-made-san-francisco/",children:"Original"}),".\nO arestare a fost f\u0103cut\u0103 \xeen cazul uciderii directorului de tehnologie Bob Lee, iar presupusul uciga\u0219 a lucrat \u0219i el \xeen domeniul tehnologiei \u0219i era cunoscut de Lee. Se pare c\u0103 poli\u021bia i-a g\u0103sit pe Lee \u0219i pe suspect conduc\xe2nd \xeempreun\u0103 \xeentr-o ma\u0219in\u0103 \xeenregistrat\u0103 pe numele suspectului \u0219i sus\u021bine c\u0103 a avut loc un fel de confruntare \xeen timp ce se aflau \xeen vehicul \u0219i c\u0103 aceasta ar fi continuat dup\u0103 ce Lee a plecat. Acoperirea mor\u021bii lui Lee a fost \xeempachetat\u0103 cu alte nenorociri \u0219i crime recente din San Francisco, de\u0219i acest lucru nu reprezint\u0103 cu exactitate experien\u021ba real\u0103 tr\u0103it\u0103 de majoritatea locuitorilor din San Francisco."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35555525",children:"Discussion Service"}),".\nUciderea unui director de tehnologie din San Francisco a st\xe2rnit discu\u021bii despre factori precum lipsa de ad\u0103post, s\u0103n\u0103tatea mintal\u0103, dependen\u021ba de droguri \u0219i s\u0103r\u0103cia care ar fi putut duce la aceast\u0103 crim\u0103, dar comentatorii avertizeaz\u0103 \xeempotriva generaliz\u0103rilor. Exist\u0103, de asemenea, o dezbatere cu privire la utilizarea statisticilor \xeen compara\u021bie cu anecdotele personale atunci c\xe2nd se evalueaz\u0103 ratele criminalit\u0103\u021bii, precum \u0219i necesitatea unei abord\u0103ri care s\u0103 implice comunitatea pentru a aborda problemele complexe ale persoanelor f\u0103r\u0103 ad\u0103post, dependen\u021bei \u0219i criminalit\u0103\u021bii. Utilizatorii eviden\u021biaz\u0103 importan\u021ba evalu\u0103rii nivelurilor de criminalitate \xeen raport cu s\u0103r\u0103cia, mai degrab\u0103 dec\xe2t compararea diferitelor culturi, \u0219i nu s\u0103 se trag\u0103 concluzii pripite pe baza unui singur caz."]}),"\n",(0,t.jsx)(i.h2,{id:"interzicerea-g\u0103zduirii-youtube-dl-deschide-calea-c\u0103tre-cenzura-privatizat\u0103",children:"Interzicerea g\u0103zduirii YouTube-DL deschide calea c\u0103tre cenzura privatizat\u0103"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://torrentfreak.com/youtube-dl-hosting-ban-paves-the-way-to-privatized-censorship-230411/",children:"Original"}),'.\nUn tribunal german a decis c\u0103 Uberspace este r\u0103spunz\u0103tor pentru g\u0103zduirea site-ului youtube-dl - un instrument open-source care permite desc\u0103rcarea con\u021binutului YouTube. Uberspace avertizeaz\u0103 c\u0103 verdictul ar putea duce la cenzura privatizat\u0103 \u0219i face apel la decizie, de\u0219i instan\u021ba a considerat c\u0103 Uberspace "poate fi tras la r\u0103spundere pentru c\u0103 a pus la \xeendoial\u0103 validitatea unei cereri de retragere", chiar \u0219i atunci c\xe2nd nu era clar c\u0103 instrumentul \xeenc\u0103lca legea.']}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35553337",children:"Discussion Service"}),".\nInterzicerea g\u0103zduirii YouTube-DL este v\u0103zut\u0103 ca un impuls c\u0103tre o cenzur\u0103 privatizat\u0103, RIAA \u0219i MPAA acord\xe2nd prioritate banilor \u0219i puterii \xeen detrimentul decen\u021bei. Rolul propriet\u0103\u021bii intelectuale \xeen limitarea fluxului de informa\u021bii este dezb\u0103tut, fiind oferite o serie de puncte de vedere, inclusiv limitarea domeniului de aplicare \u0219i a duratei. Utilizatorii propun alternative \u0219i denun\u021b\u0103 dependen\u021ba de GitHub, discut\xe2nd \xeen acela\u0219i timp despre descentralizare \u0219i despre problemele legate de securitatea prin obscuritate \xeen protec\u021bia \xeempotriva copierii."]}),"\n",(0,t.jsx)(i.h2,{id:"the-art-of-auto-engineering",children:"The art of auto engineering"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.howacarworks.com/video-course",children:"Original"}),".\nArta ingineriei auto este un curs video complet compus din peste 122 de lec\u021bii cu 20 de ore de filmare care explic\u0103 \xeen detaliu fiecare parte a unei ma\u0219ini, acoperind de la elementele de baz\u0103 p\xe2n\u0103 la ingineria auto avansat\u0103. Cursul este \xeenso\u021bit de un manual de 200 de pagini \u0219i este disponibil online sau \xeen aplica\u021biile pentru iOS \u0219i Android pentru o plat\u0103 unic\u0103 de 25 de dolari cu acces pe via\u021b\u0103, fiind filmat profesional la calitate 4K cu subtitrare complet\u0103. Cursul este l\u0103udat de c\u0103tre spectatori pentru instructajul s\u0103u captivant \u0219i valoarea excelent\u0103 a produc\u021biei."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35552393",children:"Discussion Service"}),".\nUtilizatorii Hacker News \xeemp\u0103rt\u0103\u0219esc experien\u021be \u0219i recomand\u0103 resurse pentru a \xeenv\u0103\u021ba despre ingineria auto, inclusiv cursuri video interactive \u0219i modele de ma\u0219ini specifice. Comentatorii discut\u0103 despre beneficiile \xeen\u021belegerii mecanicii auto, despre limit\u0103rile de a se baza doar pe inteligen\u021ba artificial\u0103 \u0219i ofer\u0103 sfaturi pentru repara\u021bii auto DIY. \xcen plus, utilizatorii dezbat utilitatea cursurilor \u0219i a instrumentelor pl\u0103tite, iar unii critic\u0103 apari\u021bia pe site a reclamelor pentru cursuri cu plat\u0103."]}),"\n",(0,t.jsx)(i.h2,{id:"apple-va-folosi-cobalt-100-reciclat-\xeen-baterii-p\xe2n\u0103-\xeen-2025",children:"Apple va folosi cobalt 100% reciclat \xeen baterii p\xe2n\u0103 \xeen 2025"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.apple.com/newsroom/2023/04/apple-will-use-100-percent-recycled-cobalt-in-batteries-by-2025/",children:"Original"}),".\nApple \u0219i-a anun\u021bat planul de a utiliza cobalt 100% reciclat \xeen toate bateriile proiectate de Apple p\xe2n\u0103 \xeen 2025, al\u0103turi de elemente de p\u0103m\xe2nturi rare complet reciclate pentru magne\u021bi \u0219i staniu 100% reciclat pentru pl\u0103cile de circuite. Scopul lor este de a utiliza numai materiale reciclate \u0219i regenerabile \u0219i deja se aprovizioneaz\u0103 cu peste 95% din tungsten, aproape trei sferturi din p\u0103m\xe2nturile rare \u0219i peste dou\u0103 treimi din aluminiu din materiale 100% reciclate. Apple folose\u0219te realitatea augmentat\u0103 (AR) pentru a ghida dezasamblarea dispozitivelor pentru partenerii de reciclare \u0219i pentru a cre\u0219te recuperarea elementelor de p\u0103m\xe2nturi rare, determin\xe2nd astfel o schimbare la nivelul \xeentregii industrii \xeen sensul reducerii dependen\u021bei de minerale nou extrase."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35554270",children:"Discussion Service"}),".\nApple \u0219i-a anun\u021bat planul de a utiliza cobalt 100% reciclat \xeen baterii p\xe2n\u0103 \xeen 2025 \u0219i de a reduce de\u0219eurile de plastic, dar utilizatorii dezbat eficacitatea acestor schimb\u0103ri \u0219i dac\u0103 compania ar trebui s\u0103 fac\u0103 public\u0103 tehnologia de reciclare. Dezbaterea privind bateriile care pot fi \xeenlocuite de utilizatori continu\u0103, exist\xe2nd argumente conform c\u0103rora acestea sunt negative pentru mediu, \xeen timp ce al\u021bii sugereaz\u0103 c\u0103 metodele de reciclare \u0219i extinderea duratei de via\u021b\u0103 a produselor durabile pot rezolva aceast\u0103 problem\u0103. Angajamentul Apple fa\u021b\u0103 de materialele reciclabile \u0219i fa\u021b\u0103 de un lan\u021b de aprovizionare neutru din punct de vedere al emisiilor de dioxid de carbon este l\u0103udat, dar este criticat pentru designul s\u0103u \u0219i pentru lan\u021bul de aprovizionare cu cobalt. Utilizatorii discut\u0103 despre durata de via\u021b\u0103 a iPhone-urilor \u0219i a telefoanelor Android, precum \u0219i despre metodele de reciclare a bateriilor. Unii utilizatori sugereaz\u0103 bateriile MagSafe ca baterie principal\u0103 pentru iPhone-uri, \xeen timp ce al\u021bii pun la \xeendoial\u0103 eficien\u021ba acestora."]}),"\n",(0,t.jsx)(i.h2,{id:"am-ob\u021binut-o-cre\u0219tere-de-6-ori-a-vitezei-de-pornire-a-podman",children:"Am ob\u021binut o cre\u0219tere de 6 ori a vitezei de pornire a Podman"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.redhat.com/sysadmin/speed-containers-podman-raspberry-pi",children:"Original"}),".\nMotorul de containere al Red Hat, Podman, a ob\u021binut o cre\u0219tere de 6 ori a vitezei de pornire prin eliminarea proceselor inutile \u0219i prin rezolvarea unor ineficien\u021be minore care au impact asupra aplica\u021biilor critice, cum ar fi automobilele, unde este esen\u021bial\u0103 pornirea containerelor aproape \xeen timp real. Echipa a folosit stocarea tranzitorie \u0219i a oferit solu\u021bii de rezolvare pentru problemele de kernel, ceea ce a dus la o pornire mai rapid\u0103 a containerelor. Utilizarea op\u021biunii --transient-store este ideal\u0103 pentru dispozitivele de margine, de\u0219i containerele \xeen mod mixt nu sunt acceptate."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35551830",children:"Discussion Service"}),".\nPodman de la Red Hat vede o cre\u0219tere de \u0219ase ori a vitezei de pornire a ma\u0219inilor, de\u0219i utilizatorii Discussion Service discut\u0103 despre supracomplicarea ma\u0219inilor moderne \u0219i \xee\u0219i exprim\u0103 \xeengrijorarea cu privire la fiabilitate \u0219i \xeentre\u021binere. Discu\u021bia deviaz\u0103 \xeen dezbateri privind dreptul la repara\u021bii, utilizarea microserviciilor \u0219i a containerelor \u0219i echilibrul dintre progresele tehnologice \u0219i caracterul practic."]}),"\n",(0,t.jsx)(i.h2,{id:"improving-tailscale-via-apples-open-source",children:"Improving Tailscale via Apple's open source"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://tailscale.dev/blog/darwin-spelunking",children:"Original"}),'.\nEchipa Tailscale a folosit sursa deschis\u0103 a Apple pentru a depana bug-urile legate de interfa\u021ba de re\u021bea pentru versiunea 1.36, baz\xe2ndu-se pe ifconfig pentru a determina interfa\u021ba de re\u021bea activ\u0103. Atunci c\xe2nd Tailscale este configurat pentru a utiliza un nod de ie\u0219ire, acesta devine ruta implicit\u0103, necesit\xe2nd o remediere pentru a "lega" \xeen mod constant cererile de re\u021bea la interfa\u021ba de re\u021bea activ\u0103 f\u0103r\u0103 a provoca un trafic \xeen bucl\u0103. SIOCGIFDELEGATE, disponibil prin ioctl, permite ob\u021binerea interfe\u021bei fizice subiacente \u0219i a fost implementat \xeen codul Tailscale pentru macOS \u0219i iOS.']}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35559124",children:"Discussion Service"}),".\nUtilizatorii Discussion Service discut\u0103 beneficiile \u0219i provoc\u0103rile software-ului cu surs\u0103 deschis\u0103 \u0219i \xeenchis\u0103 \xeen \xeembun\u0103t\u0103\u021birea Tailscale prin intermediul sursei deschise a Apple. Unii clien\u021bi pl\u0103titori acord\u0103 prioritate reputa\u021biei produsului de baz\u0103 open source al Tailscale, \xeen timp ce unii ridic\u0103 probleme specifice cu Tailscale, cum ar fi dificultatea de a accesa partaj\u0103rile de re\u021bea pe Windows 11 \u0219i poten\u021bialul consum al bateriei pe dispozitivele iOS. Discu\u021bia eviden\u021biaz\u0103 importan\u021ba lu\u0103rii \xeen considerare a diferitelor perspective \u0219i faptul c\u0103 Tailscale c\xe2\u0219tig\u0103 trac\u021biune fa\u021b\u0103 de Zerotier datorit\u0103 sistemului s\u0103u de plas\u0103 \u0219i implement\u0103rii continue de noi caracteristici, dar exist\u0103 preocup\u0103ri legate de venituri \u0219i de \u0219an\u021buri pentru unii utilizatori ai produsului."]}),"\n",(0,t.jsx)(i.h2,{id:"desene-animate",children:"Desene animate"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://fairanimateddrawings.com/site/home",children:"Original"}),'.\nDepozitul "Animated Drawings" de pe Github implementeaz\u0103 algoritmul descris \xeen lucrarea "A Method for Automatically Animating Children\'s Drawings of the Human Figure", permi\u021b\xe2nd utilizatorilor s\u0103 creeze anima\u021bii personalizate cu propriile personaje desenate de m\xe2n\u0103. Procesul de instalare este simplu, iar fi\u0219ierele de configurare pot fi modificate pentru a schimba diverse op\u021biuni, inclusiv formatele de ie\u0219ire \u0219i imaginile de fundal. Depozitul ofer\u0103, de asemenea, scripturi \u0219i modele pentru animarea desenelor personale, iar o demonstra\u021bie bazat\u0103 pe browser este disponibil\u0103 pentru o utilizare rapid\u0103 \u0219i u\u0219oar\u0103.']}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35561203",children:"Discussion Service"}),".\nProiectul Fair Animated Drawings anim\u0103 desenele cu ajutorul codului, disponibil \xeentr-o versiune bazat\u0103 pe browser \u0219i pe GitHub. Utilizatorii sunt interesa\u021bi de poten\u021bialul s\u0103u pentru idei de afaceri \u0219i sper\u0103 la o versiune cu aplica\u021bie Android. O lucrare relevant\u0103 privind estimarea neforealist\u0103 a pozi\u021biei, numit\u0103 Gesture3D, pare aplicabil\u0103 unui caz de utilizare specific, iar aplica\u021biile pentru YC Summer 2023 sunt deschise."]}),"\n",(0,t.jsx)(i.h2,{id:"amazon-codewhisperer-gratuit-pentru-utilizare-individual\u0103-este-acum-disponibil-\xeen-general",children:"Amazon CodeWhisperer, gratuit pentru utilizare individual\u0103, este acum disponibil \xeen general"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://aws.amazon.com/blogs/aws/amazon-codewhisperer-free-for-individual-use-is-now-generally-available/",children:"Original"}),".\nAmazon CodeWhisperer, un companion de codare AI \xeen timp real, este acum disponibil \xeen general \u0219i include un nivel CodeWhisperer Individual, care este gratuit pentru to\u021bi dezvoltatorii. Instrumentul \xeei ajut\u0103 pe dezvoltatori s\u0103 scrie cod rapid \u0219i sigur \u0219i f\u0103r\u0103 a p\u0103r\u0103si IDE-ul lor. CodeWhisperer ofer\u0103 sugestii pentru cazuri de utilizare de uz general \xeentr-o varietate de limbaje \u0219i poate filtra sau semnaliza sugestiile de cod care pot sem\u0103na cu anumite date de formare din surse deschise, contribuind la reducerea riscului de a utiliza cod poten\u021bial p\u0103rtinitor sau defectuos."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35554460",children:"Discussion Service"}),".\nAmazon CodeWhisperer este acum disponibil \xeen general, fiind compatibil cu mai multe limbaje, inclusiv Python, Java, JavaScript, TypeScript \u0219i C#. De\u0219i se pare c\u0103 Copilot este mai bun dec\xe2t CodeWhisperer, acesta din urm\u0103 este un instrument util care ar putea duce la transformarea codului generat de AI \xeen norm\u0103. \xcen plus, Amazon a lansat CodeGuru Reviewer, un instrument de inteligen\u021b\u0103 artificial\u0103 care scaneaz\u0103 codul pentru a identifica problemele \u0219i a recomanda remedieri pentru eficien\u021b\u0103 \u0219i reducerea costurilor."]}),"\n",(0,t.jsx)(i.h2,{id:"google-a-retras-deja-\u0219ase-produse-\xeen-2023",children:"Google a retras deja \u0219ase produse \xeen 2023"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://toolhub.tech/blog/Google-2023-Shutdown-Spree-6-Products-Pulled-in-Just-4-Months/",children:"Original"}),".\nGoogle a retras \u0219ase produse \xeen primele patru luni ale anului 2023, printre care se num\u0103r\u0103 concursul de programare Code Jam, platforma de socializare Google Currents, aplica\u021bia Street View, tehnologia purtabil\u0103 Google Jacquard, serviciul de jocuri \xeen cloud Google Stadia \u0219i routerul wireless Google OnHub. \xcen timp ce unele dintre aceste produse erau vechi de peste un deceniu, Google s-a confruntat cu critici pentru obiceiul s\u0103u de a pune cap\u0103t brusc unor servicii populare."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35553421",children:"Discussion Service"}),".\nGoogle a renun\u021bat la \u0219ase produse \xeen 2023, exist\xe2nd preocup\u0103ri legate de transparen\u021ba \u0219i etichetarea produselor, precum \u0219i de lipsa de sprijin pentru eforturile e\u0219uate, inclusiv Google Glass \u0219i Google Plus. \xcen timp ce unitatea de cloud este \xeen cre\u0219tere, cu o cot\u0103 de pia\u021b\u0103 de 10%, sunt exprimate \xeengrijor\u0103ri cu privire la implicarea clien\u021bilor \u0219i a dezvoltatorilor \u0219i la algoritmul de ucidere a conturilor. Utilizatorii dezbat solu\u021biile \u0219i costurile pentru \xeembun\u0103t\u0103\u021birea acurate\u021bei ChatGPT, \xeen timp ce reputa\u021bia Google de a abandona proiecte atrage critici cu privire la sprijinul acordat consumatorilor pentru produse."]}),"\n",(0,t.jsx)(i.h2,{id:"nvidia-rtx-remix-runtime-open-source-disponibil-acum",children:"Nvidia RTX Remix Runtime Open Source disponibil acum"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.nvidia.com/en-us/geforce/news/rtx-remix-runtime-open-source-download/",children:"Original"}),".\nNvidia a lansat runtime-ul RTX Remix, o platform\u0103 de modding open source pentru remasterizarea jocurilor clasice DirectX 8 \u0219i 9 cu path tracing, texturi \xeembun\u0103t\u0103\u021bite de AI \u0219i active create de utilizatori. Setul de instrumente de creare RTX Remix le permite modderilor s\u0103 atribuie noi active \u0219i lumini \xeen cadrul unei scene remasterizate \u0219i s\u0103 utilizeze instrumente AI pentru a reconstrui aspectul oric\u0103rui activ. Pe de alt\u0103 parte, runtime-ul RTX Remix capteaz\u0103 o scen\u0103 de joc, \xeenlocuie\u0219te activele la redare \u0219i injecteaz\u0103 \xeen joc tehnologia RTX, cum ar fi path tracing, DLSS 3 \u0219i Reflex."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35552378",children:"Discussion Service"}),".\nNvidia a lansat RTX Remix Runtime open-source, permi\u021b\xe2nd utilizatorilor s\u0103 joace jocuri mai vechi cu ray tracing \xeen timp real, de\u0219i nu toate jocurile vor func\u021biona. Utilizatorii Hacker News discut\u0103 despre importan\u021ba driverelor open-source fa\u021b\u0103 de driverele proprietare, despre reputa\u021bia Nvidia \u0219i despre performan\u021bele slabe ale RTX pe hardware-ul non-Nvidia. Utilizatorii speculeaz\u0103, de asemenea, cu privire la un poten\u021bial favoritism \u0219i sugereaz\u0103 sprijinirea dezvoltatorilor de criptomonede care implementeaz\u0103 scheme proof-of-work bazate exclusiv pe GPU. Un utilizator remarc\u0103 dezvoltarea de c\u0103tre Remedy a remake-urilor jocurilor Max Payne pentru PC folosind Remix \u0219i discut\u0103 despre problemele de ritm al cadrelor \u0219i de b\xe2lb\xe2ial\u0103 ale tehnologiei."]})]})}function d(e={}){const{wrapper:i}={...(0,n.R)(),...e.components};return i?(0,t.jsx)(i,{...e,children:(0,t.jsx)(s,{...e})}):s(e)}}}]);